def data():
    packet=json.loads((CASE/'数据核对_v1/地图数据包.json').read_text(encoding='utf-8'))
    jobs=json.loads((CASE/'单碎片制图_v1/任务清单.json').read_text(encoding='utf-8'))['jobs']
    ports=json.loads((CASE/'数据核对_v1/原生出口核对.json').read_text(encoding='utf-8'))
    return packet,{j['scene']:j for j in jobs},ports

def source_path(scene,jobs):
    restored=WORK/f'地图开发/提取画面核查_20261103/{scene}_完整静态复合.png'
    return restored if restored.exists() else CASE/'单碎片制图_v1'/jobs[scene]['source']

def reference_sheets():
    OUT.mkdir(exist_ok=True);packet,jobs,ports=data();f=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',18)
    with zipfile.ZipFile(WORK/'地图开发/地图测试工具/原生格数据.zip') as z:
        for start in range(0,17,6):
            sheet=Image.new('RGB',(1600,1440),'#e7d6b5');d=ImageDraw.Draw(sheet)
            for k,r in enumerate(packet['candidate_scenes'][start:start+6]):
                id=r['scene_id'];w,h=r['grid'];v=np.frombuffer(z.read(f'{r["resource_id"]}.bin'),dtype='<u4').reshape(h,w);free=(v&0x60800000)==0
                im=Image.open(source_path(id,jobs)).convert('RGB');p=ImageDraw.Draw(im)
                for y in range(h):
                    for x in range(w):
                        if x+1<w and free[y,x]!=free[y,x+1]:p.line(((x+1)*16,y*16,(x+1)*16,(y+1)*16),fill='#ff604b',width=2)
                        if y+1<h and free[y,x]!=free[y+1,x]:p.line((x*16,(y+1)*16,(x+1)*16,(y+1)*16),fill='#ff604b',width=2)
                for x in range(0,w,10):p.line((x*16,0,x*16,h*16),fill='#6b7d89',width=1);p.text((x*16+2,10),str(x),fill='white',font=f)
                for y in range(0,h,10):p.line((0,y*16,w*16,y*16),fill='#6b7d89',width=1);p.text((2,y*16+2),str(y),fill='white',font=f)
                im.thumbnail((780,420));x=k%2*800;y=k//2*480;sheet.paste(im,(x+(800-im.width)//2,y+35));d.text((x+12,y+8),f'{id} / {w} x {h}',font=f,fill='#382319')
                im.save(OUT/f'{id}-source-edges.png')
            sheet.save(OUT/f'source-edges-{start//6+1}.png')

def compile_geometry():
    OUT.mkdir(exist_ok=True);packet,jobs,ports=data();reports=[]
    sheet=Image.new('RGB',(1440,1500),'#e7d6b5');draw=ImageDraw.Draw(sheet);font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',18)
    with zipfile.ZipFile(WORK/'地图开发/地图测试工具/原生格数据.zip') as z:
        for k,r in enumerate(packet['candidate_scenes']):
            sid=r['scene_id'];w,h=r['grid'];raw=z.read(f'{r["resource_id"]}.bin');assert hashlib.sha256(raw).hexdigest()==r['grid_sha256']
            grid=np.frombuffer(raw,dtype='<u4').reshape(h,w);free=(grid&0x60800000)==0
            if sid in ENVELOPES:
                envelope=Image.new('L',(w*8,h*8));d=ImageDraw.Draw(envelope)
                for poly in ENVELOPES[sid]:d.polygon([(round(x*8),round(y*8)) for x,y in poly],fill=255)
                for poly in HOLES.get(sid,[]):d.polygon([(round(x*8),round(y*8)) for x,y in poly],fill=0)
                env=np.asarray(envelope)[4::8,4::8]>0;road=free&env
                method='native boundaries; source-traced road-side envelopes and local void outlines'
            else:
                p=CASE/'单碎片制图_v1'/jobs[sid]['display_review_v2']['file']
                alpha=np.asarray(Image.open(p).convert('RGBA'))[:,:,3]
                road=alpha[8::16,8::16]>0
                method='reused existing reviewed bounded native component and local repairs'
            incoming=[p for p in ports['return_routes'] if p['destination_scene']==sid]
            tags={p['tag'] for p in ports['return_routes'] if p['source_scene']==sid}
            active=np.isin(grid&255,list(tags))
            missing=[p['arrival_grid'] for p in incoming if not road[p['arrival_grid'][1],p['arrival_grid'][0]]]
            # Portal trigger area is display data, distinct from a walkability claim.
            display=road|active
            Image.fromarray((road*255).astype(np.uint8)).save(OUT/f'{sid}-road-grid.png')
            Image.fromarray((display*255).astype(np.uint8)).save(OUT/f'{sid}-display-grid.png')
            rgb=np.full((h,w,3),(224,206,171),np.uint8);rgb[road]=(249,237,204);rgb[(~free)]=(122,88,52)
            rgb[~display&~free]=(224,206,171)
            im=Image.fromarray(rgb).resize((w*4,h*4),Image.Resampling.NEAREST);d=ImageDraw.Draw(im)
            for p in incoming:
                x,y=p['arrival_grid'];d.ellipse((x*4-3,y*4-3,x*4+3,y*4+3),fill='#e12519' if [x,y] in missing else '#166bae')
            im.thumbnail((340,250));x=k%4*360;y=k//4*300;sheet.paste(im,(x+(350-im.width)//2,y+28));draw.text((x+5,y+4),f'{sid} / misses {len(missing)}',font=font,fill='#422a1a')
            source=source_path(sid,jobs)
            reports.append(dict(scene=sid,grid=[w,h],method=method,road_cells=int(road.sum()),incoming=[p['arrival_grid'] for p in incoming],missing_incoming=missing,
                source=str(source.relative_to(WORK)).replace('\\','/'),source_sha256=hashlib.sha256(source.read_bytes()).hexdigest(),grid_sha256=r['grid_sha256'],
                envelope=ENVELOPES.get(sid),holes=HOLES.get(sid),geometry_accepted=False,gameplay_tested=False))
    sheet.save(OUT/'geometry-review.png')
    report=dict(status='source-traced geometry candidate; portal coverage and visual review required',scenes=reports,pairs=ports['pairs'],
        no_brightness_classification=True,no_automatic_gap_closure=True,no_game_collision_changes=True)
    (OUT/'geometry.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps([dict(scene=r['scene'],cells=r['road_cells'],missing=r['missing_incoming']) for r in reports]))

if __name__=='__main__':compile_geometry()
